draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // sun
  ctx.fillStyle = 'yellow';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();

  // cloud
  ctx.fillStyle = 'white';
  ctx.beginPath();
  ctx.arc(W/2 + 100 * Math.sin(t), H/2 - 50 * Math.cos(t), 30, 0, 2 * Math.PI);
  ctx.fill();

  // tree
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2 - 50, H - 50);
  ctx.lineTo(W/2 - 50, H - 150);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W/2 - 50, H - 150, 50, 0, 2 * Math.PI);
  ctx.stroke();

  // bird
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100 + 50 * Math.sin(t), H/2 - 100 + 20 * Math.cos(t), 10, 0, 2 * Math.PI);
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(W/2 - 100 + 50 * Math.sin(t), H/2 - 90 + 20 * Math.cos(t));
  ctx.lineTo(W/2 - 90 + 50 * Math.sin(t), H/2 - 110 + 20 * Math.cos(t));
  ctx.stroke();

  ctx.restore();
}
